// ─────────────────────────── runtime tests ───────────────────────────────
//  This module is type-level: the runtime test is a token that proves the
//  values below really do have the types you wrote. The grading weight is
//  in the type tests underneath.

const label: If<true, string, number> = 'ts';
const item: Flatten1<string[]> = 'sky';

test('the typed values survive to runtime', () => {
  eq(label, 'ts');
  eq(item, 'sky');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _s1 = Expect<Equal<IsString<'hi'>, true>>;
type _s2 = Expect<Equal<IsString<string>, true>>;
type _s3 = Expect<Equal<IsString<number>, false>>;
// a union asks the question once per member, so both answers come back
type _s4 = Expect<Equal<IsString<string | number>, boolean>>;
// ...and never asks it zero times
type _s5 = Expect<IsNever<IsString<never>>>;

type _i1 = Expect<Equal<If<true, 'yes', 'no'>, 'yes'>>;
type _i2 = Expect<Equal<If<false, 'yes', 'no'>, 'no'>>;
type _i3 = Expect<Equal<If<boolean, 'yes', 'no'>, 'yes' | 'no'>>;

type _f1 = Expect<Equal<Flatten1<number[]>, number>>;
type _f2 = Expect<Equal<Flatten1<string>, string>>;
type _f3 = Expect<Equal<Flatten1<[1, 2, 3]>, 1 | 2 | 3>>;
type _f4 = Expect<Equal<Flatten1<number[][]>, number[]>>;
type _f5 = Expect<IsNever<Flatten1<[]>>>;

// @ts-expect-error — If's condition must be constrained to boolean
type _i4 = If<'yes', 1, 0>;

function _typeTests() {
  // @ts-expect-error — Flatten1<string[]> is string, not string[]
  const wrong: Flatten1<string[]> = ['a'];
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const name: UnwrapArray<string[]> = 'ada';
const port: ElementOf<readonly number[]> = 5432;

test('the unwrapped values are plain values at runtime', () => {
  eq(name, 'ada');
  eq(port, 5432);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _u1 = Expect<Equal<UnwrapArray<string[]>, string>>;
type _u2 = Expect<Equal<UnwrapArray<number>, number>>;
type _u3 = Expect<Equal<UnwrapArray<Promise<string>[]>, Promise<string>>>;
type _u4 = Expect<Equal<UnwrapArray<[1, 'a']>, 1 | 'a'>>;
// a readonly array is NOT assignable to (infer E)[] — no match, as-is
type _u5 = Expect<Equal<UnwrapArray<readonly string[]>, readonly string[]>>;

type _p1 = Expect<Equal<UnwrapPromise<Promise<number>>, number>>;
type _p2 = Expect<Equal<UnwrapPromise<Promise<Promise<1>>>, Promise<1>>>;
type _p3 = Expect<Equal<UnwrapPromise<string>, string>>;

type _e1 = Expect<Equal<ElementOf<readonly string[]>, string>>;
type _e2 = Expect<Equal<ElementOf<string[]>, string>>;
type _e3 = Expect<IsNever<ElementOf<number>>>;
type _e4 = Expect<IsNever<ElementOf<[]>>>;

function _typeTests() {
  const v: UnwrapPromise<Promise<number>> = 42;
  use(v);

  // @ts-expect-error — unwrapping Promise<number> gives number, not string
  const bad: UnwrapPromise<Promise<number>> = 'nope';
  use(bad);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const parse = (s: string) => Number.parseInt(s, 10);

const parsed: MyReturnType<typeof parse> = parse('42');
const args: MyParameters<typeof parse> = ['42'];

test('the derived types describe the real function', () => {
  eq(parsed, 42);
  eq(args, ['42']);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<MyReturnType<() => string>, string>>;
type _r2 = Expect<Equal<MyReturnType<(a: number, b: string) => boolean>, boolean>>;
type _r3 = Expect<Equal<MyReturnType<() => void>, void>>;
type _r4 = Expect<IsNever<MyReturnType<string>>>;
// must agree with the builtin, character for character
type _r5 = Expect<Equal<MyReturnType<typeof parse>, ReturnType<typeof parse>>>;

type _p1 = Expect<Equal<MyParameters<(a: string, b: number) => void>, [a: string, b: number]>>;
type _p2 = Expect<Equal<MyParameters<() => void>, []>>;
type _p3 = Expect<Equal<MyParameters<(...xs: number[]) => void>, number[]>>;
type _p4 = Expect<IsNever<MyParameters<{ a: 1 }>>>;
type _p5 = Expect<Equal<MyParameters<typeof parse>, Parameters<typeof parse>>>;

function _typeTests() {
  const n: MyReturnType<typeof parse> = 1;
  use(n);

  // @ts-expect-error — parse takes a string, so [42] is not its parameters
  const wrong: MyParameters<typeof parse> = [42];
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const head: First<[string, number]> = 'ada';
const tail: Last<[string, number]> = 1;

test('the ends of the tuple type hold real values', () => {
  eq(head, 'ada');
  eq(tail, 1);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<Equal<First<[1, 2, 3]>, 1>>;
type _t2 = Expect<Equal<Last<[1, 2, 3]>, 3>>;
type _t3 = Expect<Equal<First<['only']>, 'only'>>;
type _t4 = Expect<IsNever<First<[]>>>;
type _t5 = Expect<IsNever<Last<[]>>>;
// an unbounded array is not a non-empty tuple: it might be empty
type _t6 = Expect<IsNever<First<string[]>>>;

type _a1 = Expect<Equal<FirstArg<(a: string, b: number) => void>, string>>;
type _a2 = Expect<Equal<LastArg<(a: string, b: number) => void>, number>>;
type _a3 = Expect<Equal<FirstArg<(only: boolean) => void>, boolean>>;
type _a4 = Expect<IsNever<FirstArg<() => void>>>;
// a rest signature has no statically first or last parameter either
type _a5 = Expect<IsNever<FirstArg<(...xs: boolean[]) => void>>>;
type _a6 = Expect<IsNever<LastArg<(...xs: boolean[]) => void>>>;
type _a7 = Expect<IsNever<LastArg<'not a function'>>>;

// @ts-expect-error — First only accepts tuples and arrays
type _bad = First<string>;

function _typeTests() {
  // @ts-expect-error — Last<[1, 2, 3]> is 3, not 1
  const wrong: Last<[1, 2, 3]> = 1;
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const kept: MyExclude<'a' | 'b', 'a'> = 'b';
const defined: MyNonNullable<string | null | undefined> = 'here';

test('the filtered types hold the values that survived', () => {
  eq(kept, 'b');
  eq(defined, 'here');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _x1 = Expect<Equal<MyExclude<'a' | 'b' | 'c', 'a'>, 'b' | 'c'>>;
type _x2 = Expect<IsNever<MyExclude<'a' | 'b', 'a' | 'b'>>>;
type _x3 = Expect<Equal<MyExclude<string | number, boolean>, string | number>>;
// never is the empty union: nothing to run the filter on
type _x4 = Expect<IsNever<MyExclude<never, 'a'>>>;
type _x5 = Expect<Equal<MyExclude<'a' | 'b', 'a'>, Exclude<'a' | 'b', 'a'>>>;

type _e1 = Expect<Equal<MyExtract<'a' | 'b' | 1, string>, 'a' | 'b'>>;
type _e2 = Expect<IsNever<MyExtract<'a' | 'b', number>>>;
type _e3 = Expect<Equal<MyExtract<string | number, string>, Extract<string | number, string>>>;

type _n1 = Expect<Equal<MyNonNullable<string | null | undefined>, string>>;
type _n2 = Expect<IsNever<MyNonNullable<null>>>;
type _n3 = Expect<Equal<MyNonNullable<number | undefined>, number>>;

// the two halves of the same question, answered differently
type _b1 = Expect<Equal<IsStringLoose<string | number>, boolean>>;
type _b2 = Expect<Equal<IsStringExact<string | number>, false>>;
type _b3 = Expect<IsNever<IsStringLoose<never>>>;
// never is assignable to string, and bracketing asks about never itself
type _b4 = Expect<Equal<IsStringExact<never>, true>>;
type _b5 = Expect<Equal<IsStringExact<'lit'>, true>>;
type _b6 = Expect<Equal<IsStringExact<number>, false>>;

function _typeTests() {
  const b: MyExclude<'a' | 'b', 'a'> = 'b';
  use(b);

  // @ts-expect-error — 'a' was excluded from the union
  const gone: MyExclude<'a' | 'b', 'a'> = 'a';
  use(gone);

  // @ts-expect-error — MyNonNullable dropped null from the type
  const nulled: MyNonNullable<string | null> = null;
  use(nulled);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const leaf: Flatten<number[][]> = 3;

test('the type describes what awaiting really produces', async () => {
  const inner = Promise.resolve(7);
  const settled: DeepAwaited<Promise<Promise<number>>> = await inner;
  eq(settled, 7);
  eq(leaf, 3);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _d1 = Expect<Equal<DeepAwaited<Promise<Promise<Promise<string>>>>, string>>;
type _d2 = Expect<Equal<DeepAwaited<number>, number>>;
type _d3 = Expect<Equal<DeepAwaited<Promise<string[]>>, string[]>>;
// each union member is peeled on its own
type _d4 = Expect<Equal<DeepAwaited<Promise<string> | number>, string | number>>;
// an array of promises is not a promise — nothing to peel
type _d5 = Expect<Equal<DeepAwaited<Promise<number>[]>, Promise<number>[]>>;

type _f1 = Expect<Equal<Flatten<number[][][]>, number>>;
type _f2 = Expect<Equal<Flatten<string>, string>>;
type _f3 = Expect<Equal<Flatten<[1, [2, [3]]]>, 1 | 2 | 3>>;
type _f4 = Expect<Equal<Flatten<[number[], string[]]>, number | string>>;
type _f5 = Expect<Equal<Flatten<readonly (readonly boolean[])[]>, boolean>>;
// the empty tuple has no element type to recurse into
type _f6 = Expect<IsNever<Flatten<[]>>>;

function _typeTests() {
  // @ts-expect-error — DeepAwaited peels every layer, so this is number
  const still: DeepAwaited<Promise<Promise<number>>> = Promise.resolve(1);
  use(still);

  // @ts-expect-error — Flatten<number[][]> is number, not number[]
  const arr: Flatten<number[][]> = [1];
  use(arr);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const config: DeepReadonly<{ server: { port: number; tags: string[] } }> = {
  server: { port: 5432, tags: ['db'] },
};

test('a deeply frozen type is a plain object at runtime', () => {
  eq(config.server.port, 5432);
  eq(config.server.tags[0], 'db');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<
  Equal<DeepReadonly<{ a: { b: string } }>, { readonly a: { readonly b: string } }>
>;
type _r2 = Expect<Equal<DeepReadonly<string>, string>>;
type _r3 = Expect<Equal<DeepReadonly<number | boolean>, number | boolean>>;
// a call signature must survive: functions are objects, but not records
type _r4 = Expect<Equal<DeepReadonly<{ f: () => void }>, { readonly f: () => void }>>;
type _r5 = Expect<Equal<DeepReadonly<{ a: number[] }>, { readonly a: readonly number[] }>>;
type _r6 = Expect<Equal<DeepReadonly<{ a?: { b: 1 } }>, { readonly a?: { readonly b: 1 } }>>;
type _r7 = Expect<Equal<DeepReadonly<[1, { a: 2 }]>, readonly [1, { readonly a: 2 }]>>;
type _r8 = Expect<Equal<DeepReadonly<{}>, {}>>;

function _typeTests() {
  const cfg: DeepReadonly<{ a: { b: number } }> = { a: { b: 1 } };

  // @ts-expect-error — readonly all the way down, not just at the top
  cfg.a.b = 2;

  // @ts-expect-error — the top level is readonly too
  cfg.a = { b: 3 };

  use(cfg);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const pushed: Push<[1, 2], 3> = [1, 2, 3];
const reversed: Reverse<['a', 'b']> = ['b', 'a'];

test('the rebuilt tuple types accept exactly those values', () => {
  eq(pushed, [1, 2, 3]);
  eq(reversed, ['b', 'a']);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _p1 = Expect<Equal<Push<[1, 2], 3>, [1, 2, 3]>>;
type _p2 = Expect<Equal<Push<[], 'x'>, ['x']>>;
type _p3 = Expect<Equal<Unshift<[2, 3], 1>, [1, 2, 3]>>;

type _o1 = Expect<Equal<Pop<[1, 2, 3]>, [1, 2]>>;
type _o2 = Expect<Equal<Pop<['only']>, []>>;
// popping nothing is not an error, it's just nothing
type _o3 = Expect<Equal<Pop<[]>, []>>;
type _o4 = Expect<Equal<Shift<[1, 2, 3]>, [2, 3]>>;
type _o5 = Expect<Equal<Shift<[]>, []>>;

type _r1 = Expect<Equal<Reverse<[1, 2, 3]>, [3, 2, 1]>>;
type _r2 = Expect<Equal<Reverse<[]>, []>>;
type _r3 = Expect<Equal<Reverse<['a']>, ['a']>>;
type _r4 = Expect<Equal<Reverse<[1, 'two', true]>, [true, 'two', 1]>>;
type _r5 = Expect<Equal<Reverse<Reverse<[1, 2, 3]>>, [1, 2, 3]>>;

// @ts-expect-error — Reverse takes tuples and arrays, not strings
type _bad = Reverse<string>;

function _typeTests() {
  // @ts-expect-error — Push appends, it does not prepend
  const wrong: Push<[1, 2], 3> = [3, 1, 2];
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const parts: Split<'a,b,c', ','> = ['a', 'b', 'c'];
const trimmed: TrimLeft<'  hi'> = 'hi';

test('the type-level split matches the runtime split', () => {
  eq(parts, ['a', 'b', 'c']);
  eq(parts.join(','), 'a,b,c');
  eq(trimmed, 'hi');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _s1 = Expect<Equal<Split<'a,b,c', ','>, ['a', 'b', 'c']>>;
type _s2 = Expect<Equal<Split<'a', ','>, ['a']>>;
// the empty string is one empty piece, not zero pieces
type _s3 = Expect<Equal<Split<'', ','>, ['']>>;
type _s4 = Expect<Equal<Split<'a--b', '--'>, ['a', 'b']>>;
type _s5 = Expect<Equal<Split<'a,,b', ','>, ['a', '', 'b']>>;
type _s6 = Expect<Equal<Split<'2026-08-20', '-'>, ['2026', '08', '20']>>;

type _t1 = Expect<Equal<TrimLeft<'  hi'>, 'hi'>>;
type _t2 = Expect<Equal<TrimLeft<'\n\t hi '>, 'hi '>>;
type _t3 = Expect<Equal<TrimLeft<''>, ''>>;
type _t4 = Expect<Equal<TrimLeft<'hi'>, 'hi'>>;
type _t5 = Expect<Equal<TrimLeft<'   '>, ''>>;

function _typeTests() {
  const ok: Split<'a,b', ','> = ['a', 'b'];
  use(ok);

  // @ts-expect-error — Split returns the pieces, not the original string
  const wrong: Split<'a,b', ','> = 'a,b';
  use(wrong);

  // @ts-expect-error — TrimLeft keeps the trailing space: 'hi ', not 'hi'
  const kept: TrimLeft<'  hi '> = 'hi';
  use(kept);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const joined: Join<['a', 'b', 'c'], '-'> = 'a-b-c';
const clean: Trim<'  hi \n'> = 'hi';

test('the built-up types hold exactly those strings', () => {
  eq(joined, 'a-b-c');
  eq(joined.split('-').length, 3);
  eq(clean, 'hi');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _j1 = Expect<Equal<Join<['a', 'b', 'c'], '-'>, 'a-b-c'>>;
// one element means zero delimiters
type _j2 = Expect<Equal<Join<['a'], '-'>, 'a'>>;
type _j3 = Expect<Equal<Join<[], '-'>, ''>>;
type _j4 = Expect<Equal<Join<['a', 'b'], ''>, 'ab'>>;
type _j5 = Expect<Equal<Join<['x', 'y', 'z'], '/'>, 'x/y/z'>>;
type _j6 = Expect<Equal<Join<['2026', '08', '20'], '-'>, '2026-08-20'>>;

type _r1 = Expect<Equal<TrimRight<'hi  '>, 'hi'>>;
type _r2 = Expect<Equal<TrimRight<'  hi'>, '  hi'>>;
type _r3 = Expect<Equal<TrimRight<''>, ''>>;
type _r4 = Expect<Equal<TrimRight<' hi \n\t'>, ' hi'>>;

type _t1 = Expect<Equal<Trim<'  hi \n'>, 'hi'>>;
type _t2 = Expect<Equal<Trim<''>, ''>>;
type _t3 = Expect<Equal<Trim<'   '>, ''>>;
type _t4 = Expect<Equal<Trim<'a b'>, 'a b'>>;

// @ts-expect-error — Join only joins strings
type _bad = Join<[1, 2], '-'>;

function _typeTests() {
  // @ts-expect-error — the delimiter goes BETWEEN the pieces: 'a-b'
  const wrong: Join<['a', 'b'], '-'> = 'ab';
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const letter: StringToUnion<'abc'> = 'b';
const len: LengthOfString<'hello'> = 5;

test('the character types hold real characters', () => {
  eq(letter, 'b');
  eq(len, 5);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _u1 = Expect<Equal<StringToUnion<'abc'>, 'a' | 'b' | 'c'>>;
type _u2 = Expect<Equal<StringToUnion<'hi'>, 'h' | 'i'>>;
// duplicates collapse: a union is a set
type _u3 = Expect<Equal<StringToUnion<'aa'>, 'a'>>;
// no characters, no members — the empty string is the base case
type _u4 = Expect<IsNever<StringToUnion<''>>>;
type _u5 = Expect<Equal<StringToUnion<'a b'>, 'a' | ' ' | 'b'>>;

type _l1 = Expect<Equal<LengthOfString<'hello'>, 5>>;
type _l2 = Expect<Equal<LengthOfString<''>, 0>>;
type _l3 = Expect<Equal<LengthOfString<'a'>, 1>>;
type _l4 = Expect<Equal<LengthOfString<'  '>, 2>>;

function _typeTests() {
  const c: StringToUnion<'abc'> = 'c';
  use(c);

  // @ts-expect-error — 'd' is not one of the characters of 'abc'
  const bad: StringToUnion<'abc'> = 'd';
  use(bad);

  // @ts-expect-error — the length is the literal 5, not any number
  const wrong: LengthOfString<'hello'> = 4;
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const key: CamelCase<'created_at'> = 'createdAt';
const typeName: PascalCase<'user_id'> = 'UserId';

test('the renamed keys are those exact strings', () => {
  eq(key, 'createdAt');
  eq(typeName, 'UserId');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _c1 = Expect<Equal<CamelCase<'foo_bar_baz'>, 'fooBarBaz'>>;
type _c2 = Expect<Equal<CamelCase<'created_at'>, 'createdAt'>>;
type _c3 = Expect<Equal<CamelCase<'foo_bar'>, 'fooBar'>>;
type _c4 = Expect<Equal<CamelCase<'foo'>, 'foo'>>;
type _c5 = Expect<Equal<CamelCase<''>, ''>>;
// a trailing underscore has nothing after it to capitalise
type _c6 = Expect<Equal<CamelCase<'foo_'>, 'foo'>>;
type _c7 = Expect<Equal<CamelCase<'a_b_c_d'>, 'aBCD'>>;

type _p1 = Expect<Equal<PascalCase<'user_id'>, 'UserId'>>;
type _p2 = Expect<Equal<PascalCase<'foo'>, 'Foo'>>;
type _p3 = Expect<Equal<PascalCase<''>, ''>>;

function _typeTests() {
  const ok: CamelCase<'foo_bar'> = 'fooBar';
  use(ok);

  // @ts-expect-error — the underscore is exactly what CamelCase removes
  const wrong: CamelCase<'foo_bar'> = 'foo_bar';
  use(wrong);

  // @ts-expect-error — PascalCase capitalises the first letter too
  const lower: PascalCase<'user_id'> = 'userId';
  use(lower);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const path: PathKeys<Config> = 'server.host';

test('a path type holds a real dotted string', () => {
  eq(path, 'server.host');
  eq(path.split('.'), ['server', 'host']);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _p1 = Expect<Equal<PathKeys<Config>, 'server' | 'server.host' | 'server.port' | 'debug'>>;
type _p2 = Expect<Equal<PathKeys<{ a: { b: { c: number } } }>, 'a' | 'a.b' | 'a.b.c'>>;
type _p3 = Expect<Equal<PathKeys<{ x: string }>, 'x'>>;
// nothing to walk into
type _p4 = Expect<IsNever<PathKeys<{}>>>;
type _p5 = Expect<IsNever<PathKeys<string>>>;
// number keys can't appear in a dotted string path
type _p6 = Expect<Equal<PathKeys<{ a: number; 1: string }>, 'a'>>;
type _p7 = Expect<Equal<PathKeys<{ a?: number }>, 'a'>>;
type _p8 = Expect<Equal<PathKeys<{ a: { b: 1 }; c: { d: 2 } }>, 'a' | 'a.b' | 'c' | 'c.d'>>;

function _typeTests() {
  const p: PathKeys<Config> = 'server.port';
  use(p);

  // @ts-expect-error — 'server.nope' is not a path of Config
  const bad: PathKeys<Config> = 'server.nope';
  use(bad);

  // @ts-expect-error — 'host' on its own is not a top-level path
  const partial: PathKeys<Config> = 'host';
  use(partial);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const config: Config = {
  server: { host: 'localhost', port: 5432 },
  flags: { beta: true },
  name: 'tsbootcamp',
};

test('reads a top-level value', () => {
  eq(get(config, 'name'), 'tsbootcamp');
});

test('reads a nested value', () => {
  eq(get(config, 'server.host'), 'localhost');
});

test('reads a nested number', () => {
  eq(get(config, 'server.port'), 5432);
});

test('returns the whole branch when the path stops early', () => {
  eq(get(config, 'flags'), { beta: true });
});

test('walks three levels down', () => {
  const deep = { a: { b: { c: 'leaf' } } };
  eq(get(deep, 'a.b.c'), 'leaf');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _g1 = Expect<Equal<Get<Config, 'server.host'>, string>>;
type _g2 = Expect<Equal<Get<Config, 'server.port'>, number>>;
type _g3 = Expect<Equal<Get<Config, 'server'>, { host: string; port: number }>>;
type _g4 = Expect<Equal<Get<Config, 'name'>, string>>;
type _g5 = Expect<Equal<Get<{ a: { b: { c: 1 } } }, 'a.b.c'>, 1>>;
// a segment that isn't a key stops the walk
type _g6 = Expect<IsNever<Get<Config, 'server.nope'>>>;
type _g7 = Expect<IsNever<Get<Config, 'nope'>>>;

type _f1 = Expect<Equal<ReturnType<typeof get<Config, 'server.port'>>, number>>;
type _f2 = Expect<Equal<ReturnType<typeof get<Config, 'flags'>>, { beta: boolean }>>;

function _typeTests() {
  const host: string = get(config, 'server.host');
  use(host);

  // @ts-expect-error — 'server.nope' is not a path of Config
  get(config, 'server.nope');

  // @ts-expect-error — 'host' is not a top-level path of Config
  get(config, 'host');

  // @ts-expect-error — server.host is a string, not a number
  const wrong: number = get(config, 'server.host');
  use(wrong);
}
use(_typeTests);

